  return `<section class="portfolio-hub panel"><div class="section-head"><div><p class="eyebrow">CARTEIRA DE OBRAS</p><h2>Visão geral operacional</h2><p class="muted">Selecione uma obra para abrir o Obra 360 ou use um atalho para entrar no fluxo já filtrado.</p></div><span class="tag">${obras.length} obras locais</span></div><div class="metrics"><div><strong>${progresso}%</strong><span>avanço médio</span></div><div><strong>${totalRdos}</strong><span>RDOs recentes</span></div><div><strong>${totalPendencias}</strong><span>pendências abertas</span></div><div><strong>${obras.filter((obra) => obra.status === 'em_execucao').length}</strong><span>em execução</span></div></div><div class="quick-module-grid"><button class="quick-module" data-quick-module="frentes"><strong>Frentes de serviço</strong><span>Subfrentes, checklist e responsáveis</span></button><button class="quick-module" data-quick-module="planejamento"><strong>Planejamento</strong><span>Etapas, prazos e avanço físico</span></button><button class="quick-module" data-quick-module="rdo"><strong>Diário de obra</strong><span>RDO, evidências e ocorrências</span></button><button class="quick-module" data-quick-module="dre"><strong>Financeiro da obra</strong><span>Orçado, realizado e resultado</span></button></div></section>`;
