function adicionarNavegacaoObra() {
  const workspace = document.querySelector('.workspace');
  if (!workspace || workspace.querySelector('.obra-anchors')) return;
  const children = [...workspace.children];
  const columns = children.filter((item) => item.classList.contains('columns'));
  const rdo = children.find((item) => item.classList.contains('rdo-panel'));
  const calculator = children.find((item) => item.querySelector?.('h3')?.textContent.trim() === 'Calculadoras e memórias');
  const targets = [
    ['Indicadores', children.find((item) => item.classList.contains('metrics')), 'obra-indicadores'],
    ['Etapas e pendências', columns[0], 'obra-planejamento'],
    ['RDO', rdo, 'obra-rdo'],
    ['Cálculos', calculator, 'obra-calculos'],
    ['Materiais e documentos', columns[1], 'obra-arquivos']
  ].filter(([, element]) => element);
  targets.forEach(([, element, id]) => { element.id = id; });
  const pendenciasPanel = [...workspace.querySelectorAll('.panel')].find((panel) => panel.querySelector('h3')?.textContent.includes('Pendências'));
  if (pendenciasPanel) {
    const seen = new Set();
    [...pendenciasPanel.querySelectorAll('.row')].forEach((row) => { const key = row.textContent.trim(); if (seen.has(key)) row.remove(); else seen.add(key); });
    const metric = [...workspace.querySelectorAll('.metrics div')].find((item) => item.textContent.includes('pendências abertas'));
    if (metric?.querySelector('strong')) metric.querySelector('strong').textContent = String(seen.size);
  }
  const nav = document.createElement('nav');
  nav.className = 'obra-anchors';
  nav.setAttribute('aria-label', 'Navegação rápida da obra');
  nav.innerHTML = targets.map(([label, , id]) => `<a href="#${id}">${label}</a>`).join('');
  workspace.querySelector('.section-head')?.after(nav);
}

function renderStructuralAnalysisResult() { const resultado = structuralAnalysisResult; const deslocamentos = Object.entries(resultado.displacement ?? {}); const maxUy = Math.max(...deslocamentos.map(([, value]) => Math.abs(value.uy)), 0); const maxUx = Math.max(...deslocamentos.map(([, value]) => Math.abs(value.ux)), 0); return `<section class="panel structural-result-panel"><div class="panel-head"><div><p class="eyebrow">ANÁLISE LINEAR 2D</p><h3>Resultados preliminares</h3><p class="muted">Modelo resolvido com comportamento linear-elástico. Revise hipóteses e combinações antes de qualquer decisão de projeto.</p></div><button class="small ghost" id="limparAnaliseEstrutural">Limpar</button></div><div class="metrics"><div><strong>${deslocamentos.length}</strong><span>nós processados</span></div><div><strong>${resultado.elements?.length ?? 0}</strong><span>elementos</span></div><div><strong>${maxUx.toExponential(3)}</strong><span>máx. deslocamento X</span></div><div><strong>${maxUy.toExponential(3)}</strong><span>máx. deslocamento Y</span></div></div><div class="structural-result-table">${deslocamentos.map(([id, value]) => `<div class="row"><span><strong>${esc(id)}</strong><small class="muted">ux · uy · rotação</small></span><span>${Number(value.ux).toExponential(3)} · ${Number(value.uy).toExponential(3)} · ${Number(value.rz).toExponential(3)}</span></div>`).join('')}</div></section>`; }
