  const porPeriodo = [...new Set(itens.map((item) => item.periodo))].sort().map((periodo) => { const rows = itens.filter((item) => item.periodo === periodo); return { periodo, planejado: rows.reduce((sum, item) => sum + Number(item.planejado), 0), realizado: rows.reduce((sum, item) => sum + Number(item.realizado), 0) }; });
