  if (moduleId === 'compras') { const obra = obraAtualOuPrimeira(); return obra ? renderComprasWorkspace(obra) : `<section class="workspace"><div class="empty"><h2>Cadastre uma obra antes de usar este módulo</h2><button class="small" id="novaObraModulo">+ Nova obra</button></div></section>`; }
