  if (moduleId === 'medicoes') return `<section class="workspace">${header}<div class="panel"><div class="panel-head"><div><h3>Medições de serviço</h3><p class="muted">Registre quantidade, preço unitário e status de aprovação.</p></div><button class="small" id="novaMedicao">+ Nova medição</button></div>${(obra.medicoes ?? []).map((m) => `<div class="row"><span><strong>${esc(m.descricao)}</strong><small class="muted">${esc(m.frente_nome ?? 'Sem frente')} · ${esc(m.periodo ?? 'sem período')}</small></span><span>${Number(m.quantidade).toFixed(2)} ${esc(m.unidade)} · ${brlReais(Number(m.quantidade) * Number(m.preco_unitario))}<select class="inline-status" data-medicao-status="${esc(m.id)}"><option value="rascunho" ${m.status === 'rascunho' ? 'selected' : ''}>Rascunho</option><option value="enviada" ${m.status === 'enviada' ? 'selected' : ''}>Enviada</option><option value="aprovada" ${m.status === 'aprovada' ? 'selected' : ''}>Aprovada</option><option value="rejeitada" ${m.status === 'rejeitada' ? 'selected' : ''}>Rejeitada</option></select></span></div>`).join('') || '<p class="muted">Nenhuma medição cadastrada.</p>'}</div></section>`;
  return `<section class="workspace">${header}<div class="panel"><div class="panel-head"><div><h3>Contratos e aditivos</h3><p class="muted">Controle de fornecedor, objeto, valor e alterações contratuais.</p></div><button class="small" id="novoContrato">+ Novo contrato</button></div>${(obra.contratos ?? []).map((c) => `<div class="contract-row"><div><strong>${esc(c.fornecedor)}</strong><small class="muted">${esc(c.objeto)} · ${esc(c.status)} · ${brlReais(Number(c.valor) + (c.aditivos ?? []).reduce((sum, a) => sum + Number(a.valor), 0))}</small></div><button class="small" data-novo-aditivo="${esc(c.id)}">Adicionar aditivo</button></div>`).join('') || '<p class="muted">Nenhum contrato cadastrado.</p>'}</div></section>`;
