function resumoResultados(value, prefix = '') { if (value == null) return []; if (typeof value === 'object') return Object.entries(value).flatMap(([key, item]) => resumoResultados(item, `${prefix}${key}.`)); return [`${prefix.replace(/\.$/, '')}: ${typeof value === 'number' ? Number(value.toFixed(4)) : value}`]; }
function resumoCalculo(resultado) { if (!resultado || typeof resultado !== 'object') return resumoResultados(resultado); const { entrada, metadados, ...blocos } = resultado; return resumoResultados(blocos); }
function renderObraEnhanced(obra) {
  const etapas = obra.etapas ?? []; const progresso = etapas.length ? etapas.reduce((s, e) => s + Number(e.percentual_concluido), 0) / etapas.length : 0; const custoMateriais = (obra.materiais ?? []).reduce((s, m) => s + Number(m.quantidade_realizada) * Number(m.custo_unitario), 0);
  return `<section class="workspace"><div class="section-head"><div><p class="eyebrow">OBRA 360</p><h2>${esc(obra.nome)}</h2><p>${esc(obra.codigo)} · ${esc(obra.responsavel_tecnico ?? 'Responsável não informado')}</p></div><span class="tag">${esc(obra.status)}</span></div><div class="metrics"><div><strong>${progresso.toFixed(0)}%</strong><span>avanço médio</span></div><div><strong>${obra.rdos?.length ?? 0}</strong><span>RDOs</span></div><div><strong>${obra.pendencias?.filter((p) => p.status !== 'resolvida').length ?? 0}</strong><span>pendências abertas</span></div><div><strong>${brlReais(custoMateriais)}</strong><span>custo realizado</span></div></div><div class="columns"><div class="panel"><div class="panel-head"><h3>Etapas</h3><button class="small" id="novaEtapa">Adicionar</button></div>${etapas.length ? etapas.map((e) => `<div class="row"><span>${esc(e.nome)}<small class="muted">${esc(e.responsavel ?? '')}</small></span><b>${Number(e.percentual_concluido).toFixed(0)}%</b></div>`).join('') : '<p class="muted">Nenhuma etapa cadastrada.</p>'}</div><div class="panel"><div class="panel-head"><h3>Pendências e riscos</h3><button class="small" id="novaPendencia">Adicionar</button></div>${obra.pendencias?.length ? obra.pendencias.slice(0, 6).map((p) => `<div class="row"><span>${esc(p.descricao)}</span><span class="priority">${esc(p.prioridade)}</span></div>`).join('') : '<p class="muted">Nenhuma pendência cadastrada.</p>'}</div></div><div class="panel rdo-panel"><div class="panel-head"><h3>RDO</h3><div><button class="small" id="pdfUltimoRdo">PDF do último</button><button class="small" id="novoRdo">Novo RDO</button></div></div>${obra.rdos?.length ? obra.rdos.slice(0, 5).map((r) => `<div class="row"><span>${esc(r.data)} · ${esc(r.responsavel)}</span><span>${(r.servicosExecutados ?? []).length} serviços · ${(r.fotos ?? []).length} fotos</span></div>`).join('') : '<p class="muted">Nenhum RDO registrado.</p>'}</div><div class="panel"><div class="panel-head"><h3>Calculadoras e memórias</h3><button class="small" id="novoCalculo">Novo cálculo</button></div>${obra.calculos?.length ? obra.calculos.slice(0, 5).map((c) => `<div class="row"><span>${esc(c.titulo)}<small class="muted">${esc(c.norma ?? '')}</small></span><button class="small" data-pdf-calculo="${esc(c.id)}">PDF</button></div>`).join('') : '<p class="muted">Nenhum cálculo salvo nesta obra.</p>'}</div><div class="columns"><div class="panel"><div class="panel-head"><h3>Materiais e custos</h3><button class="small" id="novoMaterial">Adicionar</button></div>${obra.materiais?.length ? obra.materiais.map((m) => `<div class="row"><span>${esc(m.material)}</span><span>${Number(m.quantidade_realizada)} ${esc(m.unidade ?? '')} · ${brlReais(Number(m.quantidade_realizada) * Number(m.custo_unitario))}</span></div>`).join('') : '<p class="muted">Nenhum material cadastrado.</p>'}</div><div class="panel"><div class="panel-head"><h3>Documentos locais</h3><button class="small" id="novoDocumento">Adicionar</button></div>${obra.documentos?.length ? obra.documentos.map((d) => `<div class="row"><span>${esc(d.nome)}</span><span>${esc(d.tipo ?? 'arquivo')}</span></div>`).join('') : '<p class="muted">Nenhum documento cadastrado.</p>'}</div></div></section>`;
}

function abrirModalRdoCompleto() { modal('Novo RDO completo', `<label>Data<input name="data" type="date" required value="${new Date().toISOString().slice(0, 10)}" /></label><label>Turno<input name="turno" placeholder="Diurno" /></label><label>Responsável<input name="responsavel" required /></label><label>Clima<input name="clima" placeholder="Ensolarado, chuva, temperatura..." /></label><label>Equipes<textarea name="equipes" placeholder="Ex.: Carpinteiros;4\nPedreiros;3"></textarea></label><label>Serviços executados<textarea name="servicos" required placeholder="Um serviço por linha"></textarea></label><label>Materiais recebidos<textarea name="materiais" placeholder="Ex.: Concreto;6;m³\nAço;1200;kg"></textarea></label><label>Ocorrências<textarea name="ocorrencias"></textarea></label><label>Impedimentos<textarea name="impedimentos" placeholder="Um impedimento por linha"></textarea></label><label>Fotos<input name="fotos" type="file" accept="image/*" multiple /></label><label>Observações<textarea name="observacoes"></textarea></label>`, async (f) => { const linhas = (name) => String(f.get(name) ?? '').split('\n').map((item) => item.trim()).filter(Boolean); const equipes = linhas('equipes').map((item) => { const [funcao, quantidade] = item.split(';'); return { funcao, quantidade: Number(quantidade ?? 0) }; }); const materiaisRecebidos = linhas('materiais').map((item) => { const [material, quantidade, unidade] = item.split(';'); return { material, quantidade: Number(quantidade ?? 0), unidade }; }); const fotos = []; for (const file of Array.from(f.get('fotos') ?? [])) { const bytes = new Uint8Array(await file.arrayBuffer()); let bin = ''; bytes.forEach((byte) => { bin += String.fromCharCode(byte); }); fotos.push({ uri: `data:${file.type};base64,${btoa(bin)}`, legenda: file.name }); } salvarRdo(db, obraSelecionada.id, { data: f.get('data'), turno: f.get('turno'), responsavel: f.get('responsavel'), clima: { condicao: f.get('clima') }, equipes, servicosExecutados: linhas('servicos').map((descricao) => ({ descricao })), materiaisRecebidos, ocorrencias: linhas('ocorrencias').map((descricao) => ({ descricao })), impedimentos: linhas('impedimentos').map((descricao) => ({ descricao, resolvido: false })), fotos, observacoes: f.get('observacoes') }); obraSelecionada = buscarObra(db, obraSelecionada.id); obras = listarObras(db); render(); }); }

function wireExtendedEvents() {
  document.querySelector('#novoCalculo')?.addEventListener('click', abrirModalCalculo); document.querySelector('#novoMaterial')?.addEventListener('click', abrirModalMaterial); document.querySelector('#novoDocumento')?.addEventListener('click', abrirModalDocumento);
  document.querySelectorAll('[data-pdf-calculo]').forEach((el) => el.addEventListener('click', () => { const calc = obraSelecionada.calculos.find((item) => item.id === el.dataset.pdfCalculo); if (calc) baixarPdfTexto(`Memória de cálculo - ${calc.titulo}`, [obraSelecionada.nome, calc.tipo, calc.norma ?? '', ...resumoResultados(calc.entradas, 'entrada.'), '', ...resumoResultados(calc.resultados, 'resultado.')]); }));
}

function abrirModalCalculo() { const opcoes = Object.entries(CALCULADORAS).map(([key, item]) => `<option value="${key}">${item.label}</option>`).join(''); const campos = (CALCULADORAS.vigaBiapoiada.fields).map(([key, label, value]) => `<label>${label}<input name="${key}" type="number" step="any" value="${value}" /></label>`).join(''); modal('Novo cálculo', `<label>Calculadora<select name="tipo" id="tipoCalculo">${opcoes}</select></label><div id="camposCalculo">${campos}</div>`, (f) => { const tipo = f.get('tipo'); const def = CALCULADORAS[tipo]; const entradas = Object.fromEntries(def.fields.map(([key]) => [key, Number(f.get(key))])); const resultado = def.fn(entradas); const validacao = validarCalculoIndependente(tipo, entradas, resultado); if (!validacao.ok) { alert(`Cálculo reprovado na validação independente:\n${validacao.errors.join('\n')}`); return; } salvarCalculo(db, obraSelecionada.id, { tipo, titulo: def.label, entradas, resultados: { ...resultado, validacao }, norma: resultado.metadados?.normaDeclarada }); obraSelecionada = buscarObra(db, obraSelecionada.id); obras = listarObras(db); render(); }); setTimeout(() => document.querySelector('#tipoCalculo')?.addEventListener('change', (event) => { const def = CALCULADORAS[event.target.value]; document.querySelector('#camposCalculo').innerHTML = def.fields.map(([key, label, value]) => `<label>${label}<input name="${key}" type="number" step="any" value="${value}" /></label>`).join(''); }), 0); }
function abrirModalMaterial() { modal('Material da obra', `<label>Material<input name="material" required /></label><label>Unidade<input name="unidade" placeholder="kg, m, un" /></label><label>Quantidade planejada<input name="planejada" type="number" step="any" value="0" /></label><label>Quantidade realizada<input name="realizada" type="number" step="any" value="0" /></label><label>Custo unitário<input name="custo" type="number" step="any" value="0" /></label>`, (f) => { salvarMaterial(db, obraSelecionada.id, { material: f.get('material'), unidade: f.get('unidade'), quantidadePlanejada: Number(f.get('planejada')), quantidadeRealizada: Number(f.get('realizada')), custoUnitario: Number(f.get('custo')) }); obraSelecionada = buscarObra(db, obraSelecionada.id); obras = listarObras(db); render(); }); }
function abrirModalDocumento() { modal('Documento local', `<label>Nome<input name="nome" required /></label><label>Arquivo<input name="arquivo" type="file" /></label>`, async (f) => { const file = f.get('arquivo'); let dadosBase64 = null; if (file?.size) { const bytes = new Uint8Array(await file.arrayBuffer()); let bin = ''; bytes.forEach((byte) => { bin += String.fromCharCode(byte); }); dadosBase64 = btoa(bin); } salvarDocumento(db, obraSelecionada.id, { nome: f.get('nome') || file?.name, tipo: file?.type, dadosBase64 }); obraSelecionada = buscarObra(db, obraSelecionada.id); obras = listarObras(db); render(); }); }
function baixarPdfTexto(titulo, lines) { const blob = gerarPdfRelatorio(titulo, { Memória: lines }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `${titulo.replace(/[^a-z0-9]+/gi, '-')}.pdf`; a.click(); URL.revokeObjectURL(a.href); }
function baixarBlob(nome, blob) { const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = nome; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 1000); }

abrirBanco().then((database) => { db = database; obras = listarObras(db); render(); }).catch((error) => { app.innerHTML = `<main class="error"><h1>Não foi possível abrir o banco local</h1><p>${esc(error.message)}</p></main>`; });
